(()=>{
 'use strict';
 const S=Site,C=Cimora,E=S.esc;
 const ownId='local-creator',tabs=[['works','作品发布'],['assets','资产包上架'],['income','收益与结算']];
 let avatarDraft=null;
 function profile(){let value;try{value=StudioLibrary.meta().profile;}catch{}return {id:ownId,name:S.state.prefs.studio||'我的工作室',bio:'',avatar:'',...value};}
 function author(item){return item?.authorId===ownId||item?.local||item?.author==='我的工作室'?profile().name:item?.author||'创作者';}
 function avatar(value=profile(),cls=''){return `<span class="sa-avatar ${cls}">${value.avatar?`<img src="${E(value.avatar)}" alt="创作者头像">`:E(Array.from(value.name)[0]||'创')}</span>`;}
 const link=(text,path,primary=false)=>C.link(text,path,'cm-button '+(primary?'primary':'ghost'));
 function centerHeader(tab){const p=profile();return `<header class="sa-heading sa-creator-heading"><div><span class="cm-kicker">YOUR CREATOR SPACE</span><h1>创作者中心</h1><p>管理作品发布、资产包上架与创作收益。</p></div><div class="sa-creator-identity">${avatar(p)}<strong>${E(p.name)}</strong><div class="sa-actions">${link('编辑资料','/app/settings?tab=profile')}${link('公开主页','/app/creator/profile')}</div></div></header><nav class="sa-tabs" aria-label="创作者中心">${tabs.map(([id,label])=>`<a href="#/app/creator?tab=${id}" aria-current="${tab===id?'page':'false'}">${label}</a>`).join('')}</nav>`;}
 function settings(){const p=profile(),requested=S.context.params.get('tab'),tab=['account','wallet','purchases','profile'].includes(requested)?requested:'account';avatarDraft=null;return `<div class="sa-page"><header class="sa-heading"><div><span class="cm-kicker">MAKE IT YOURS</span><h1>个人中心</h1><p>管理积分钱包、购买记录、订阅额度和个人资料。</p></div>${link('进入创作者中心','/app/creator?tab=works')}</header><nav class="sa-tabs pw-personal-tabs" aria-label="个人中心">${[['account','订阅与用量'],['wallet','积分钱包'],['purchases','我的购买'],['profile','资料与设置']].map(([id,title])=>'<a href="#/app/settings?tab='+id+'" aria-current="'+(id===tab?'page':'false')+'">'+title+'</a>').join('')}</nav>${tab==='wallet'?PointsWallet.wallet():tab==='purchases'?PointsWallet.purchases():tab==='account'?AccountUsage.subscription()+AccountUsage.usage():''}${tab==='profile'?`<div class="sa-columns"><form data-sa-form="profile" class="cm-panel sa-form"><h2>创作者资料</h2><p>作品广场与创作市场共用这份公开资料。</p><div class="sa-avatar-editor"><span id="sa-avatar-preview">${avatar(p)}</span><div><div class="sa-actions"><label class="cm-button ghost">更换头像<input id="sa-avatar-file" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><button type="button" class="cm-button ghost" data-sa="remove-avatar">恢复默认</button></div><small>PNG、JPG、WebP；自动缩小后保存。</small></div></div><label>公开名称<input name="name" maxlength="40" required value="${E(p.name)}"></label><label>创作者简介<textarea name="bio" rows="3" maxlength="300" placeholder="你喜欢创作什么，想把怎样的世界带给大家？">${E(p.bio)}</textarea></label><p class="sa-note">修改后同步展示到你的作品和资产包；历史订单、许可与交付记录保留原版本。</p><p id="sa-profile-message" role="status"></p><div class="sa-actions"><button class="cm-button primary" type="submit">保存创作者资料</button>${link('查看公开主页','/app/creator/profile')}</div></form><div class="sa-stack"><section class="cm-panel sa-form"><h2>使用偏好</h2><p>当前界面使用简体中文。</p><button type="button" class="cm-button ghost" data-appearance="open">调整外观 ↗</button><form data-sa-form="preferences"><label class="sa-check"><input name="notify" type="checkbox" ${S.state.prefs.notify?'checked':''}>任务结束时显示站内提示</label><button class="cm-button ghost" type="submit">保存使用偏好</button><p id="sa-preferences-message" role="status"></p></form></section><section class="cm-panel sa-form"><h2>数据管理</h2><p>备份项目、资产、工具成果、发布作品、购买交付与导出文件，恢复时可继续本机体验。</p><p class="sa-note">包含浏览器已保存的媒体；依赖电脑原文件、临时预览或外部链接的素材仍需保留原文件。恢复或清除前请关闭其他创作标签页。</p><div class="sa-actions"><button type="button" class="cm-button ghost" data-sd="backup">下载完整备份</button><label class="cm-button ghost">从备份恢复<input type="file" id="sd-restore-file" accept="application/json,.json" hidden></label></div><p id="sd-status" role="status"></p><hr><button type="button" class="cm-button ghost" data-sd="reset">清除本机创作数据…</button><small>仅清除本产品在当前浏览器的记录，电脑原文件保留。</small></section></div></div>`:''}</div>`;}
 function communityReady(){const state=CommunityStudio.status();if(!state.loaded&&!state.loading&&!state.failure)void CommunityStudio.refresh();return state;}
 function works(){const state=communityReady(),rows=CommunityStudio.mine();return `<div class="sa-page">${centerHeader('works')}<section class="cm-panel sa-form"><div class="sa-heading"><div><h2>已发布的作品</h2><p>原稿在项目里继续创作，这里管理已保存的发布版本。</p></div><button type="button" class="cm-button primary" data-cg="publish">发布我的作品</button></div>${state.failure?`<p role="alert">${E(state.failure)}</p><button class="cm-button ghost" data-cg="reload">重新读取</button>`:''}${!state.loaded?'<p role="status">正在读取作品…</p>':rows.length?rows.map(w=>`<article class="sa-item"><div><h3>${E(w.title)}</h3><p>${E({story:'故事',comic:'漫画',video:'视频',tool:'图像与声音'}[w.kind])} · ${w.chapters?.length||1}集 · ${w.visibility==='private'?'仅自己可见':'广场展示'} · ${E(w.status||'已发布')}</p>${w.demoOnly?'<small>静态演示成品，不开放收费。</small>':''}</div><div class="sa-actions">${link('查看作品','/app/community/'+encodeURIComponent(w.id))}<button type="button" class="cm-button ghost" data-cg="settings" data-id="${E(w.id)}">修改展示设置</button>${w.sourceURL?link('继续创作',w.sourceURL):''}</div></article>`).join(''):'<div class="sa-empty"><h3>还没有发布作品</h3><p>完成故事正文、漫画成稿或视频演示成品后，可以在这里发布。</p>'+link('去我的项目','/app/projects')+'</div>'}</section></div>`;}
 function income(){communityReady();return '<div class="sa-page">'+centerHeader('income')+PointsWallet.income()+'</div>';}
 function publicProfile(){const state=communityReady(),p=profile(),works=CommunityStudio.mine().filter(w=>w.visibility==='square'),listings=MarketStudio.all().filter(item=>item.local);return `<div class="sa-page"><div class="sa-actions">${link('返回创作者中心','/app/creator?tab=works')}${link('编辑创作者资料','/app/settings?tab=profile')}</div><header class="sa-public">${avatar(p)}<h1>${E(p.name)}</h1><p>${E(p.bio||'这里记录着我的创作。')}</p><small>公开主页本机预览 · 仅展示公开作品与已上架资产包</small></header><section class="cm-panel sa-form"><h2>作品</h2>${!state.loaded?'<p role="status">正在读取作品…</p>':works.map(w=>`<article class="sa-item"><strong>${E(w.title)}</strong>${link('查看作品','/app/community/'+encodeURIComponent(w.id))}</article>`).join('')||'<p>暂未公开作品。</p>'}</section><section class="cm-panel sa-form"><h2>资产包</h2>${listings.map(item=>`<article class="sa-item"><strong>${E(item.title)}</strong>${link('查看商品','/app/market/'+encodeURIComponent(item.id))}</article>`).join('')||'<p>暂未上架资产包。</p>'}</section></div>`;}
 async function avatarImage(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('请选择 10MB 以内的 PNG、JPG 或 WebP 图片。');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas');canvas.width=160;canvas.height=160;const size=Math.min(bitmap.width,bitmap.height);canvas.getContext('2d').drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,160,160);return canvas.toDataURL('image/webp',0.8);}finally{bitmap.close();}}
 document.addEventListener('change',async event=>{if(event.target.id!=='sa-avatar-file')return;try{avatarDraft=await avatarImage(event.target.files[0]);document.getElementById('sa-avatar-preview').innerHTML=avatar({...profile(),avatar:avatarDraft});}catch(error){document.getElementById('sa-profile-message').textContent=error.message;}});
 document.addEventListener('click',event=>{if(!event.target.closest('[data-sa="remove-avatar"]'))return;avatarDraft='';document.getElementById('sa-avatar-preview').innerHTML=avatar({...profile(),avatar:''});});
 document.addEventListener('submit',async event=>{
  const form=event.target.closest('[data-sa-form]');if(!form)return;event.preventDefault();const button=form.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;
  const message=form.querySelector('[role=status]'),data=new FormData(form);
  try{
   if(form.dataset.saForm==='profile'){const name=String(data.get('name')).trim(),bio=String(data.get('bio')).trim(),picture=avatarDraft;if(!name||name.length>40||bio.length>300)throw Error('请填写 1–40 字公开名称，简介不超过 300 字。');await StudioLibrary.changeMeta(meta=>{meta.profile={...profile(),...meta.profile,id:ownId,name,bio,...(picture===null?{}:{avatar:picture})};});S.render();S.toast('创作者资料已保存，作品与资产包展示已同步');}
   else{const previous=S.state.prefs.notify;S.state.prefs.notify=data.has('notify');if(!S.save()){S.state.prefs.notify=previous;throw Error('使用偏好未能保存，请重试。');}message.textContent='使用偏好已保存。';}
  }catch(error){message.textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}
 });
 const route=C.route;C.route=ctx=>{if(ctx.parts[0]==='app'){if(ctx.parts[1]==='community'&&ctx.params.get('view')==='earnings'){ctx.parts=['app','creator'];ctx.params=new URLSearchParams('tab=income');history.replaceState(null,'','#/app/creator?tab=income');}if(['settings','billing','wallet'].includes(ctx.parts[1])){S.pageTitle='个人中心';if(ctx.parts[1]==='wallet')ctx.params.set('tab','wallet');return settings();}if(ctx.parts[1]==='creator'){if(ctx.parts[2]==='profile')return publicProfile();const tab=ctx.params.get('tab');if(!tab||tab==='works')return works();if(tab==='income')return income();}}return route(ctx);};
 window.StudioAccount={profile,author,avatar,centerHeader};
})();
